          answer: `# ओजोन विघटन: कारण और उपाय

## ओजोन विघटन के कारण

### 1. CFC (क्लोरोफ्लोरोकार्बन) - मुख्य कारण

| स्रोत | उपयोग |
|-------|--------|
| **एयर कंडीशनर** | शीतलन |
| **रेफ्रिजरेटर** | खाद्य संरक्षण |
| **एयरोसोल स्प्रे** | परफ्यूम, कीटनाशक |
| **फोम** | पैकेजिंग सामग्री |

### 2. अन्य कारण

| रसायन | उपयोग |
|--------|--------|
| हैलॉन | अग्निशामक |
| कार्बन टेट्राक्लोराइड | औद्योगिक |
| मिथाइल ब्रोमाइड | कृषि |

### 3. विघटन प्रक्रिया
- CFC वायुमंडल में पहुँचता है
- UV से Cl परमाणु अलग होते हैं
- एक Cl ~1,00,000 ओजोन अणु नष्ट करता है

---

## ओजोन विघटन के प्रभाव

### मानव स्वास्थ्य
| प्रभाव | विवरण |
|--------|--------|
| त्वचा कैंसर | मेलेनोमा |
| मोतियाबिंद | आँखों की बीमारी |
| रोग प्रतिरोधक क्षमता | कमजोर |

### पर्यावरण
| प्रभाव | विवरण |
|--------|--------|
| फसल उत्पादन | कमी |
| समुद्री जीव | प्लैंकटन मृत्यु |
| पारिस्थितिकी | असंतुलन |

---

## उपाय

### व्यक्तिगत स्तर
1. CFC-मुक्त उपकरण खरीदें
2. पुराने AC/फ्रिज बदलें
3. पर्यावरण अनुकूल उत्पाद उपयोग करें
4. जागरूकता फैलाएँ

### राष्ट्रीय/अंतर्राष्ट्रीय स्तर
1. मॉन्ट्रियल प्रोटोकॉल का पालन
2. CFC उत्पादन पर प्रतिबंध
3. वैकल्पिक तकनीक विकास
4. शिक्षा और जागरूकता

---

## निष्कर्ष
ओजोन परत पृथ्वी की सुरक्षा कवच है। हमें CFC का उपयोग बंद करके इसे बचाना होगा।`
