          answer: `# ओजोन परत का महत्व

## ओजोन परत क्या है?

| विवरण | जानकारी |
|--------|----------|
| सूत्र | O₃ |
| स्थान | समताप मंडल (15-35 किमी) |
| कार्य | UV किरणों को रोकना |

---

## महत्व (MNEMONIC: सू-प-र-क)

### 1. सूर्य से सुरक्षा
- हानिकारक UV किरणों को रोकती है
- पृथ्वी तक UV-C नहीं पहुँचने देती
- जीवन को संभव बनाती है

### 2. पृथ्वी की ढाल
| कार्य | महत्व |
|-------|--------|
| सुरक्षा कवच | अंतरिक्ष से आने वाली किरणों से बचाव |
| तापमान नियंत्रण | पृथ्वी का तापमान संतुलित |

### 3. रोग से बचाव
| बीमारी | बचाव |
|---------|--------|
| त्वचा कैंसर | UV-B से |
| मोतियाबिंद | आँखों की सुरक्षा |
| प्रतिरोधक क्षमता | बनी रहती है |

### 4. कृषि संरक्षण
- फसलों को UV से बचाती है
- खाद्य उत्पादन बना रहता है
- पारिस्थितिकी तंत्र संतुलित

---

## ओजोन परत के बिना पृथ्वी

| क्षेत्र | प्रभाव |
|--------|--------|
| मानव | कैंसर महामारी |
| पौधे | प्रकाश संश्लेषण बाधित |
| समुद्र | प्लैंकटन नष्ट |
| जलवायु | असंतुलन |

---

## निष्कर्ष
ओजोन परत के बिना पृथ्वी पर जीवन असंभव है। यह हमारी प्राकृतिक सुरक्षा कवच है।`
