          answer: `# CFC (क्लोरोफ्लोरोकार्बन)

## परिचय

| विवरण | जानकारी |
|--------|----------|
| पूरा नाम | क्लोरोफ्लोरोकार्बन |
| तत्व | क्लोरीन, फ्लोरीन, कार्बन |
| प्रकृति | मानव निर्मित रसायन |

---

## उपयोग

| क्षेत्र | उत्पाद |
|--------|--------|
| शीतलन | AC, रेफ्रिजरेटर |
| स्प्रे | एयरोसोल |
| फोम | पैकेजिंग |
| सॉल्वेंट | औद्योगिक |

---

## ओजोन पर प्रभाव

### विघटन प्रक्रिया
1. CFC वायुमंडल में पहुँचता है
2. UV से Cl अलग होता है
3. Cl ओजोन से मिलता है
4. ओजोन टूट जाता है

### भयावह तथ्य
> एक Cl परमाणु ~1,00,000 ओजोन अणु नष्ट करता है!

---

## समाधान
- CFC का उपयोग बंद
- HFC, HFO जैसे विकल्प
- मॉन्ट्रियल प्रोटोकॉल का पालन`
