          answer: `# लोकगीत

## परिभाषा
> लोक में प्रचलित, मौखिक परंपरा से पीढ़ी दर पीढ़ी हस्तांतरित गीतों को लोकगीत कहते हैं।

---

## मुख्य विशेषताएँ

| विशेषता | विवरण |
|---------|--------|
| **रचनाकार** | अज्ञात (लोक में जन्मे) |
| **परंपरा** | मौखिक (Oral Tradition) |
| **भाषा** | क्षेत्रीय बोली |
| **शैली** | सरल, लयबद्ध, गेय |

### अन्य विशेषताएँ
1. **सरल भाषा** - आम लोगों की भाषा
2. **लयबद्ध** - गाने में आसान
3. **जीवन से जुड़े** - रोज़मर्रा के विषय
4. **सामूहिक** - समूह में गाए जाते हैं

---

## विषय-वस्तु

| विषय | उदाहरण |
|-------|--------|
| **प्रेम** | प्रेम गीत |
| **विरह** | वियोग के गीत |
| **प्रकृति** | ऋतु गीत |
| **त्योहार** | उत्सव गीत |
| **श्रम** | काम के गीत |

---

## महत्व

### सांस्कृतिक महत्व
| पहलू | महत्व |
|-------|--------|
| संरक्षण | संस्कृति का संरक्षण |
| पहचान | क्षेत्रीय पहचान |
| परंपरा | परंपराओं का हस्तांतरण |

### साहित्यिक महत्व
1. लोक भाषा का अध्ययन
2. लोक जीवन की झलक
3. सामाजिक इतिहास
4. मनोरंजन

---

## निष्कर्ष
लोकगीत भारतीय संस्कृति की अमूल्य धरोहर हैं जो हमारी परंपराओं और मूल्यों को संजोए हुए हैं।`
